<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ config('app.name') }}</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Outfit:wght@500;600;700;800&display=swap" rel="stylesheet"><style>:root{--ink:#12211c;--green:#087852;--lime:#d3f05b;--cream:#f7f8f3;--line:#e7ebe7;--muted:#66736c;--red:#c13c3c}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif}h1,h2,h3{font-family:Outfit,sans-serif;margin-top:0}a{color:inherit}.topbar{background:#102c22;color:#eaf6ec;font-size:.82rem;padding:9px max(5%,24px);display:flex;justify-content:space-between}.navbar{padding:16px max(5%,24px);background:#fff;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:20px;flex-wrap:wrap}.brand{font:800 1.45rem Outfit;color:var(--green);text-decoration:none;letter-spacing:-.6px}.brand span{color:#f1a80a}.navlinks{display:flex;gap:17px;align-items:center;flex:1}.navlinks a{text-decoration:none;font-size:.93rem;font-weight:700;color:#395047}.navlinks a:hover{color:var(--green)}main{max-width:1240px;margin:0 auto;padding:32px 24px 56px}.card{background:#fff;border:1px solid var(--line);box-shadow:0 8px 30px rgba(18,33,28,.04);padding:22px;border-radius:16px;margin:16px 0}.btn,button{border:0;background:var(--green);color:#fff;border-radius:10px;padding:11px 16px;font:700 .9rem 'DM Sans';cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;justify-content:center;gap:6px}.btn:hover,button:hover{filter:brightness(.93)}.btn.light{background:#ebf5ed;color:var(--green)}.btn.yellow{background:var(--lime);color:#173524}input,select{border:1px solid #d9e1db;background:#fff;border-radius:9px;padding:11px 12px;font:500 .92rem 'DM Sans';color:var(--ink);max-width:100%}input:focus,select:focus{outline:3px solid #d9f2e7;border-color:var(--green)}table{width:100%;border-collapse:collapse}th{color:var(--muted);font-size:.75rem;text-transform:uppercase;letter-spacing:.05em;background:#f6f8f6}th,td{padding:13px;text-align:left;border-bottom:1px solid var(--line)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:16px}.stat{font:800 2.2rem Outfit}.muted{color:var(--muted)}.ok{color:#087852;font-weight:700}.error{color:#a81f1f;background:#ffeae8;padding:12px;border-radius:10px}.badge{font-size:.73rem;border-radius:99px;padding:5px 9px;font-weight:700;background:#e8f7ef;color:#087852}.badge.empty{background:#ffe9e8;color:#ad302b}.page-head{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:20px}.page-head p{margin:0;color:var(--muted)}.action-form{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.action-form input,.action-form select{margin:0}.flash{margin-bottom:12px}.footer{background:#102c22;color:#dce9e0;padding:35px max(5%,24px);display:flex;justify-content:space-between;gap:15px;flex-wrap:wrap}@media(max-width:720px){.navlinks{order:3;width:100%;overflow:auto}.topbar{display:none}main{padding:22px 14px}.card{padding:15px}.page-head{align-items:start;flex-direction:column}table{font-size:.83rem;display:block;overflow:auto}}nav[aria-label="Pagination Navigation"] svg{display:block;width:20px;height:20px;flex:none}</style></head><body><div class="topbar"><span>Minimarket YAPA · El Alto, La Paz</span><span>Productos esenciales, atención cercana</span></div><nav class="navbar"><a class="brand" href="{{ route('catalog') }}">YA<span>PA</span></a><div class="navlinks">@auth<a href="{{ route('dashboard') }}">Panel</a>@if(auth()->user()->hasPermission('manage-catalog'))<a href="{{ route('products.index') }}">Productos</a><a href="{{ route('categories.index') }}">Categorías</a>@endif @if(auth()->user()->hasPermission('view-inventory'))<a href="{{ route('inventory.index') }}">Inventario</a>@endif @if(auth()->user()->hasPermission('register-sales'))<a href="{{ route('sales.index') }}">Ventas</a>@endif @if(auth()->user()->hasPermission('view-reports'))<a href="{{ route('reports.index') }}">Reportes</a>@endif @if(auth()->user()->hasPermission('manage-users'))<a href="{{ route('users.index') }}">Usuarios</a>@endif @endauth</div>@auth <span class="muted">{{ auth()->user()->name }}</span><form method="post" action="{{ route('logout') }}">@csrf<button class="btn light">Salir</button></form>@else <a class="btn" href="{{ route('login') }}">Ingresar</a>@endauth</nav><main>@if(session('success'))<p class="flash ok">✓ {{ session('success') }}</p>@endif @if($errors->any())<div class="error">{{ $errors->first() }}</div>@endif @yield('content')</main><footer class="footer"><strong>MINIMARKET YAPA</strong><span>Gestión de inventario y ventas · Sistema interno</span></footer></body></html>
